def trapezoid_lengths():
    p=dict(A=(0,0),B=(0,5),C=(7,5),D=(12,0),H=(7,0))
    sides=[('A','B'),('B','C'),('C','D'),('D','A')]
    frames=[('Данные трапеции','ABCD',[],sides),('Высота из C','ABCDH',[],sides+[('C','H')]),
            ('Боковая сторона и BD','ABCDH',[('C','D'),('B','D')],sides+[('C','H')]),
            ('Диагональ AC','ABCDH',[('A','C')],sides+[('C','H')])]
    cases=[('Длина '+a+'→'+b,'ABCDH',[(a,b)],sides+[('C','H')]) for a,b in ['BD','CD','AC']]
    pic=scene(p,frames,cases)
    for i,key in enumerate(['neutral','step-1','step-2','step-3','case-1','case-2','case-3']):
        pic['views'][key]['rightAngles']=[dict(vertex=f'A__v{i}',a=f'B__v{i}',b=f'D__v{i}',size=2)]
        if i:pic['views'][key]['rightAngles'].append(dict(vertex=f'H__v{i}',a=f'C__v{i}',b=f'D__v{i}',size=2))
    return make(934,kind='exercise',pages=[229],title='Задача 934',
        statement='В прямоугольной трапеции ABCD основание AD имеет длину 12 см, сторона AB у прямого угла A равна 5 см, а угол D равен 45°. Найди длины B→D, C→D и A→C.',
        hint='У B→D уже известны оба катета. Для двух других стрелок опусти из C высоту CH на AD и посмотри на треугольник CDH.',
        result='В сантиметрах: |B→D|=13, |C→D|=5√2, |A→C|=√74. Каждому радикалу соответствует свой прямоугольный треугольник.',
        stages=[('Что даёт угол 45°?', 'Опустим CH перпендикулярно AD. Высота CH=AB=5. У прямоугольного треугольника CDH угол D равен 45°, поэтому второй острый угол тоже 45°. Значит, DH=CH=5, а AH=12−5=7.', 'В прямоугольном треугольнике с углом 45° катеты равны.'),
                ('Как найти BD и CD?', 'Для BD используй треугольник ABD: BD²=5²+12²=169. Для CD пригодится маленький треугольник CHD: CD²=5²+5²=50. Получаем 13 и 5√2 см соответственно.', 'Из двух разных пар катетов получаются две разные гипотенузы.'),
                ('Какой треугольник содержит AC?', 'У треугольника AHC катеты AH=7 и CH=5, поэтому AC²=49+25=74. Выбери стрелку A→C и проследи, какой горизонтальный отрезок ей соответствует.', 'Длина вектора не меняется от того, к какой вершине направлено его острие.')],
        picture=pic,checks=[None,check('Чему равен квадрат длины CD в квадратных сантиметрах?', '50','Для CD оба катета равны 5. Число 169 относится к BD.'),
                            check('Если AD=15, AB=6, а угол D по-прежнему 45°, чему теперь равен квадрат AC?', '117','В новом чертеже DH=6, AH=9, высота 6. Сложи 81 и 36.')])


def side_directions():
    from itertools import combinations, product
    def arrow(word):return word[0]+'→'+word[1]
    def list_pairs(items):return ', '.join(arrow(x)+' и '+arrow(y) for x,y in items)
    designs=[
        ('а','параллелограмма MNPQ',dict(M=(0,0),N=(4,0),P=(5,3),Q=(1,3)),'MNPQ',
         [(['MN','QP'],['NM','PQ']),(['NP','MQ'],['PN','QM'])],
         ['MN QP','MN PQ','NP MQ','NP QM'],'4','12',
         'У другого параллелограмма четыре стороны. Сколько неупорядоченных пар коллинеарных именованных стрелок получится на них, включая пары разворотов одной стороны?'),
        ('б','трапеции ABCD с основаниями AD и BC',dict(A=(0,0),B=(1,3),C=(4,3),D=(6,0)),'ABCD',
         [(['AD','BC'],['DA','CB']),(['AB'],['BA']),(['DC'],['CD'])],
         ['AD BC','AD CB','AB BA','DC CD'],'2','4',
         'Из четырёх стрелок на двух основаниях другой трапеции сколько неупорядоченных пар направлены противоположно?'),
        ('в','треугольника FGH',dict(F=(0,0),G=(5,0),H=(1,3)),'FGH',
         [(['FG'],['GF']),(['GH'],['HG']),(['HF'],['FH'])],['FG GF','GH HG','HF FH'],'0','3',
         'В другом невырожденном треугольнике сколько неупорядоченных пар противоположно направленных стрелок дают все его стороны?')]
    cards=[]
    for part,shape,p,vertices,groups,examples,same_answer,transfer_answer,transfer_q in designs:
        sides=list(zip(vertices,vertices[1:]+vertices[0]))
        same=[];opposite=[]
        for out,back in groups:
            same.extend(combinations(out,2));same.extend(combinations(back,2));opposite.extend(product(out,back))
        same_text=list_pairs(same) if same else 'разных сонаправленных стрелок нет'
        opposite_text=list_pairs(opposite)
        families='; '.join(', '.join(arrow(word) for word in out+back) for out,back in groups)
        exp=[tuple(x.split()) for x in examples]
        cases=[(arrow(w)+' и '+arrow(v),vertices,[tuple(w),tuple(v)],sides) for w,v in exp]
        viz=scene(p,[('Контур фигуры',vertices,[],sides),
                     ('Одна прямая или параллельные',vertices,[tuple(w) for w in exp[0]],sides),
                     ('Проверь ориентацию',vertices,[tuple(w) for w in exp[1]],sides),
                     ('Сопоставь стрелки',vertices,[tuple(w) for w in exp[-1]],sides)],cases)
        cards.append(make(935,kind='exercise',part=part,pages=[229],title='Задача 935',
            statement=f'Рассмотри стороны {shape}. На каждой стороне возможны две стрелки между её концами. Перечисли пары коллинеарных стрелок и раздели их по направлению. Пару разных обозначений учитывай один раз.',
            hint='Прежде чем смотреть на острия, собери в одну группу все стрелки на параллельных прямых или на общей прямой.',
            result='Сонаправленные: '+same_text+'. Противоположно направленные: '+opposite_text+'.',
            stages=[('Какие стрелки можно сравнивать по направлению?', 'Сгруппируй обе ориентации каждой стороны по прямым. Получаются такие группы: '+families+'. Из разных групп пара не будет коллинеарной.', 'Коллинеарные ненулевые векторы лежат на одной прямой или на параллельных прямых.'),
                    ('Какие пары сонаправлены?', 'Внутри каждой группы сравни острия двух стрелок. Сонаправленные: '+same_text+'. Две записи одной и той же стрелки в пару не включаем.', 'Сонаправленным стрелкам разрешено иметь разные длины.'),
                    ('Какие пары направлены противоположно?', 'Возьми из той же группы по одной стрелке каждого направления. Получится: '+opposite_text+'. Записанный в обратном порядке тот же набор имён не нужно считать ещё раз.', 'Разворот одной стороны всегда даёт пару противоположно направленных векторов.')],
            checks=[None,check('Сколько разных неупорядоченных пар сонаправленных стрелок получилось?',same_answer,('На одной стороне треугольника стрелки между её концами смотрят в разные стороны. Разные стороны не параллельны.' if part=='в' else 'Запиши каждую подходящую пару обозначений один раз. Отдельно проверь обе ориентации каждой пары параллельных сторон.')),
                    check(transfer_q,transfer_answer,'Сначала запиши векторы в каждую сторону вдоль каждой группы параллельных прямых. Затем попарно сравни их, считая каждый набор имён один раз.')],picture=viz))
    return cards


def parallelogram_equalities():
    p=dict(A=(0,0),B=(4,0),C=(5,3),D=(1,3),O=(2.5,1.5))
    sides=[('A','B'),('B','C'),('C','D'),('D','A'),('A','C'),('B','D')]
    examples=[
        ('а','AB','DC',True,'Противоположные стороны параллелограмма равны и параллельны. A→B и D→C обходят разные стороны в одну сторону.',
         'Если |A→B| равна 8 см, какова длина равного вектора D→C, в см?', '8',
         'Из трёх стрелок длины 5: вправо, влево и вправо — сколько равны первой?', '2'),
        ('б','BC','DA',False,'BC и DA имеют равные длины, но B→C идёт вверх по боковой стороне, а D→A — обратно вниз по параллельной стороне.',
         'Сколько из стрелок B→C и D→A направлены так же, как B→C?', '1',
         'Длины двух противоположно направленных ненулевых стрелок равны 6. Сколько из них надо развернуть, чтобы обе стали равны второй?', '1'),
        ('в','AO','OC',True,'Точка O делит диагональ AC пополам. Обе стрелки направлены от A к C, а AO=OC, поэтому векторы равны.',
         'Если AC=14 см, какова длина O→C, в см?', '7',
         'У другого параллелограмма AO=9 см. Какова длина всей диагонали AC, в см?', '18'),
        ('г','AC','BD',False,'AC и BD — разные диагонали. Их прямые пересекаются в O и не совпадают. Значит, эти ненулевые векторы неколлинеарны и не могут быть равны.',
         'В квадрате диагонали равны по длине. Сколько из двух стрелок A→C и B→D направлены параллельно A→C?', '1',
         'У прямоугольника диагонали по 10 см. Сколько пар равных векторов получается из единственной пары его стрелок A→C и B→D?', '0')]
    cards=[]
    for part,x,y,equal,reason,q1,a1,q2,a2 in examples:
        name=lambda pair:pair[0]+'→'+pair[1]
        pictures=[('Исходная фигура','ABCDO',[],sides),('Первая стрелка','ABCDO',[tuple(x)],sides),
                  ('Сравни две стрелки','ABCDO',[tuple(x),tuple(y)],sides),
                  ('Направление и длина','ABCDO',[tuple(x),tuple(y)],sides)]
        cards.append(make(936,kind='exercise',part=part,pages=[229],title='Задача 936',
            statement=f'У параллелограмма ABCD диагонали пересекаются в O. Сравни векторы {name(x)} и {name(y)} и объясни своё решение.',
            hint='Определи начало и конец каждой стрелки. Если направления совпадают, останется сравнить длины.',
            result=('Да. ' if equal else 'Нет. ')+reason,
            stages=[('Где начинается первая стрелка?', f'Отметь {x[0]} как начало, {x[1]} как конец. Затем для второй стрелки возьми начало {y[0]} и конец {y[1]}. Сохрани этот порядок на своём чертеже.', 'Перестановка двух букв меняет направление ненулевого вектора.'),
                    ('Какие свойства фигуры помогают?',reason,'У параллелограмма противоположные стороны равны и параллельны, а диагонали точкой пересечения делятся пополам.'),
                    ('Как обосновать окончательный ответ?', ('Укажи оба условия: одинаковые длины и одинаковое направление.' if equal else 'Укажи, какое условие равенства нарушается. Для отрицательного ответа достаточно одного такого условия.'), 'Равенство векторов проверяют по направлению и длине одновременно.')],
            picture=scene(p,pictures),checks=[None,check(q1,a1,reason),check(q2,a2,'Повтори проверку на новых данных. Сначала проверь направление, затем длину.')]))
    return cards


def build():
    return dict(bookId=BOOK,lessons=foundations()+practical()+directions()+equal_pairs()+applied_vectors()+[trapezoid_lengths()]+side_directions()+parallelogram_equalities())


if __name__ == '__main__':
    parser=argparse.ArgumentParser()
    parser.add_argument('--check',action='store_true')
    args=parser.parse_args()
    serialized=json.dumps(build(),ensure_ascii=False,separators=(',',':'))+'\n'
    if args.check:
        assert OUT.read_text()==serialized
    else:
        OUT.write_text(serialized)
